  "measure_id": "MEAS-B86CB391",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Preempts local minimum wage laws by voiding any city ordinance that sets a minimum wage and making minimum wage regulation exclusively a state power."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§1",
      "concern_id": "C21",
      "effect": "moves",
      "direction": "Shifts authority over minimum wage from cities to the state",
      "quote": "The state occupies the whole field of minimum wage regulation. Any city ordinance setting a minimum wage is void.",
      "mechanism": "It explicitly voids existing city-level minimum wage rules and asserts exclusive state control over the regulatory field.",
      "certainty": "stated"
    },
    {
      "id": "f2",
      "clause_id": "§1",
      "concern_id": "C11",
      "effect": "costs",
      "direction": null,
      "quote": "Any city ordinance setting a minimum wage is void.",
      "mechanism": "It eliminates the local ordinances that currently allow minimum wages to be set higher than the state minimum, removing that higher wage floor for workers in those cities.",
      "certainty": "stated"
    },
    {
      "id": "f3",
      "clause_id": "§1",
      "concern_id": "C08",
      "effect": "advances",
      "direction": null,
      "quote": "Any city ordinance setting a minimum wage is void.",
      "mechanism": "It lowers mandated labor costs for businesses in cities that previously set a higher minimum wage, and it replaces a patchwork of local municipal regulations with a single statewide wage standard.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Under current law, cities have the authority to set a minimum wage higher than the state minimum. This measure removes that authority, voids any existing local minimum wage ordinances, and makes minimum wage regulation exclusively a state matter.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q2",
      "answer": "Workers in cities with local minimum wage ordinances will face a direct cost in the form of lost potential earnings as their wage floor drops to the state minimum. The state may face minor administrative costs to communicate the change, while cities lose the administrative costs of enforcing their local ordinances.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "Businesses operating in cities that currently have higher minimum wages benefit from reduced mandated labor costs and simpler compliance. Low-wage workers in those same cities bear the cost through lower minimum guaranteed pay.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Businesses may shift hiring or expansion plans to cities they previously avoided due to higher local wage mandates. Workers facing lower guaranteed wages might seek additional hours, change jobs to find higher pay, or increase their reliance on public assistance programs to cover living expenses.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses the compliance complexity and uneven labor costs created for businesses by a patchwork of local wage regulations. The mechanism reaches this by establishing uniform state preemption. On the other hand, it removes the ability of cities to address local problems, such as a high local cost of living that the state minimum wage may not cover.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "State legislators gain exclusive power to set minimum wages. City councils lose the discretion to tailor wage requirements to their local economies. Employers in previously higher-wage cities gain greater leverage over entry-level pay rates.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "The effect of minimum wage changes on jobs and investment is empirically disputed. Some researchers find that eliminating higher local wage mandates increases hiring, business expansion, and youth employment. Other researchers find that higher minimum wages have minimal negative effects on employment and instead reduce worker turnover and increase productivity.",
      "disputed": true
    }
  ],
